FUNCTION acyclic_alternative_solution_relationship(relation : alternative_solution_relationship;
                                                   relatives : SET [1:?] OF product_definition_formation;
                                                   specific_relation : STRING) : BOOLEAN;
  LOCAL
    x : SET OF alternative_solution_relationship;
  END_LOCAL;
  IF relation.relating_product_definition_formation IN relatives THEN
    RETURN (FALSE);
  END_IF;
  x := QUERY(asr <* bag_to_set(USEDIN(relation.relating_product_definition_formation, ('PRODUCT_DEFINITION_SCHEMA.' + 'ALTERNATIVE_SOLUTION_RELATIONSHIP.') + 'RELATED_PRODUCT_DEFINITION_FORMATION')) | specific_relation IN TYPEOF(asr));
  REPEAT i := 1 TO HIINDEX(x);
    IF NOT acyclic_alternative_solution_relationship(x[i], relatives + relation.relating_product_definition_formation, specific_relation) THEN
      RETURN (FALSE);
    END_IF;
  END_REPEAT;
  RETURN (TRUE);
END_FUNCTION;

