SCHEMA product_property_definition_schema '{iso standard 10303 part(41) version(9) object(1) product_property_definition_schema(19)}';

REFERENCE FROM basic_attribute_schema
  (get_id_value,
   id_attribute,
   id_attribute_select);
REFERENCE FROM process_property_schema
  (action_property,
   resource_property);
REFERENCE FROM product_definition_schema
  (product_definition,
   product_definition_relationship,
   product_definition_relationship_relationship);
REFERENCE FROM product_property_representation_schema
  (item_identified_representation_usage);
REFERENCE FROM product_structure_schema
  (assembly_component_usage,
   multi_level_reference_designator,
   next_assembly_usage_occurrence,
   product_definition_occurrence);
REFERENCE FROM shape_dimension_schema
  (dimensional_location,
   dimensional_size);
REFERENCE FROM shape_tolerance_schema
  (geometric_tolerance);
REFERENCE FROM support_resource_schema
  (bag_to_set,
   identifier,
   label,
   text);

