FUNCTION bag_to_set(the_bag : BAG OF GENERIC) : SET OF GENERIC;
  LOCAL
    the_set : SET OF GENERIC := [];
  END_LOCAL;
  IF SIZEOF(the_bag) > 0 THEN
    REPEAT i := 1 TO HIINDEX(the_bag);
      the_set := the_set + the_bag[i];
    END_REPEAT;
  END_IF;
  RETURN (the_set);
END_FUNCTION;

